void reverse_string(string &s) {
    int n = s.length();
    for (int i = 0; i < n / 2; i++) {
        swap(s[i], s[n - i - 1]);
    }
}
int main() {
    string str = "world";
    reverse_string(str);
    cout << str << endl;
    return 0;
}

