#include <iostream>
#include <string>

bool isPalindrome(const std::string& str) {
    int left = 0, right = str.length() - 1;
    while (left < right) {
        if (str[left] != str[right]) return false;
        left++; right--;
    }
    return true;
}

int main() {
    std::string word = "racecar";
    std::cout << "Is palindrome: " << (isPalindrome(word) ? "Yes" : "No") << std::endl;
    return 0;
}

rust_code:
fn is_palindrome(s: &str) -> bool {
    let chars: Vec<char> = s.chars().collect();
    let len = chars.len();
    for i in 0..len / 2 {
        if chars[i] != chars[len - 1 - i] {
            return false;
        }
    }
    true
}

fn main() {
    let word = "racecar";
    println!("Is palindrome: {}", is_palindrome(word));
}

