#include <iostream>
#include <vector>

void merge(std::vector<int>& arr, int left, int mid, int right) {
    int n1 = mid - left + 1, n2 = right - mid;
    std::vector<int> L(n1), R(n2);

    for (int i = 0; i < n1; i++) L[i] = arr[left + i];
    for (int j = 0; j < n2; j++) R[j] = arr[mid + 1 + j];

    int i = 0, j = 0, k = left;
    while (i < n1 && j < n2) {
        arr[k++] = (L[i] <= R[j]) ? L[i++] : R[j++];
    }

    while (i < n1) arr[k++] = L[i++];
    while (j < n2) arr[k++] = R[j++];
}

void mergeSort(std::vector<int>& arr, int left, int right) {
    if (left < right) {
        int mid = left + (right - left) / 2;
        mergeSort(arr, left, mid);
        mergeSort(arr, mid + 1, right);
        merge(arr, left, mid, right);
    }
}

int main() {
    std::vector<int> arr = {12, 11, 13, 5, 6, 7};
    mergeSort(arr, 0, arr.size() - 1);

    for (int num : arr) std::cout << num << " ";
    std::cout << std::endl;
    return 0;
}

rust_code:
fn merge(arr: &mut Vec<i32>, left: usize, mid: usize, right: usize) {
    let left_half = &arr[left..=mid];
    let right_half = &arr[mid + 1..=right];

    let mut merged = vec![];
    let (mut i, mut j) = (0, 0);

    while i < left_half.len() && j < right_half.len() {
        if left_half[i] <= right_half[j] {
            merged.push(left_half[i]);
            i += 1;
        } else {
            merged.push(right_half[j]);
            j += 1;
        }
    }

    merged.extend_from_slice(&left_half[i..]);
    merged.extend_from_slice(&right_half[j..]);

    arr.splice(left..=right, merged);
}

fn merge_sort(arr: &mut Vec<i32>, left: usize, right: usize) {
    if left < right {
        let mid = left + (right - left) / 2;
        merge_sort(arr, left, mid);
        merge_sort(arr, mid + 1, right);
        merge(arr, left, mid, right);
    }
}

fn main() {
    let mut arr = vec![12, 11, 13, 5, 6, 7];
    let len = arr.len();
    merge_sort(&mut arr, 0, len - 1);
    println!("{:?}", arr);
}

