#include <iostream>

struct Node {
    int data;
    Node* next;
    Node(int val) : data(val), next(nullptr) {}
};

Node* mergeLists(Node* l1, Node* l2) {
    if (!l1) return l2;
    if (!l2) return l1;

    if (l1->data < l2->data) {
        l1->next = mergeLists(l1->next, l2);
        return l1;
    } else {
        l2->next = mergeLists(l1, l2->next);
        return l2;
    }
}

void printList(Node* head) {
    while (head) {
        std::cout << head->data << " ";
        head = head->next;
    }
    std::cout << std::endl;
}

int main() {
    Node* l1 = new Node(1);
    l1->next = new Node(3);
    l1->next->next = new Node(5);

    Node* l2 = new Node(2);
    l2->next = new Node(4);
    l2->next->next = new Node(6);

    Node* merged = mergeLists(l1, l2);
    printList(merged);
    return 0;
}

rust_code:
struct Node {
    data: i32,
    next: Option<Box<Node>>,
}

impl Node {
    fn new(val: i32) -> Self {
        Self { data: val, next: None }
    }
}

fn merge_lists(l1: Option<Box<Node>>, l2: Option<Box<Node>>) -> Option<Box<Node>> {
    match (l1, l2) {
        (None, l) => l,
        (l, None) => l,
        (Some(mut n1), Some(mut n2)) => {
            if n1.data < n2.data {
                n1.next = merge_lists(n1.next, Some(n2));
                Some(n1)
            } else {
                n2.next = merge_lists(Some(n1), n2.next);
                Some(n2)
            }
        }
    }
}

fn print_list(mut head: Option<Box<Node>>) {
    while let Some(node) = head {
        print!("{} ", node.data);
        head = node.next;
    }
    println!();
}

fn main() {
    let mut l1 = Some(Box::new(Node::new(1)));
    l1.as_mut().unwrap().next = Some(Box::new(Node::new(3)));
    l1.as_mut().unwrap().next.as_mut().unwrap().next = Some(Box::new(Node::new(5)));

    let mut l2 = Some(Box::new(Node::new(2)));
    l2.as_mut().unwrap().next = Some(Box::new(Node::new(4)));
    l2.as_mut().unwrap().next.as_mut().unwrap().next = Some(Box::new(Node::new(6)));

    let merged = merge_lists(l1, l2);
    print_list(merged);
}

