use std::sync::{Arc, Mutex};
use std::thread;

fn print_hello(mtx: Arc<Mutex<()>>) {
    let _lock = mtx.lock().unwrap();
    println!("Hello from thread!");
}

fn main() {
    let mtx = Arc::new(Mutex::new(()));
    let mtx1 = Arc::clone(&mtx);
    let mtx2 = Arc::clone(&mtx);

    let t1 = thread::spawn(move || print_hello(mtx1));
    let t2 = thread::spawn(move || print_hello(mtx2));

    t1.join().unwrap();
    t2.join().unwrap();
}

