void reverse_string(std::string& str) {
    int n = str.length();
    for (int i = 0; i < n / 2; i++) {
        std::swap(str[i], str[n - i - 1]);
    }
}

int main() {
    std::string text = "hello";
    reverse_string(text);
    std::cout << "Reversed: " << text << std::endl;
    return 0;
}

