int fibonacci_iterative(int n) {
    if (n <= 1) return n;
    int a = 0, b = 1, temp;
    for (int i = 2; i <= n; i++) {
        temp = a + b;
        a = b;
        b = temp;
    }
    return b;
}

int main() {
    std::cout << "Fibonacci(7): " << fibonacci_iterative(7) << std::endl;
    return 0;
}

rust_code:
fn fibonacci_iterative(n: u32) -> u32 {
    if n <= 1 {
        return n;
    }
    let (mut a, mut b) = (0, 1);
    for _ in 2..=n {
        let temp = a + b;
        a = b;
        b = temp;
    }
    b
}

fn main() {
    println!("Fibonacci(7): {}", fibonacci_iterative(7));
}

