    vec.iter().cloned().filter(|&x| x > threshold).collect()
}

fn main() {
    let numbers = vec![2, 7, 3, 10, 5];
    let filtered = filter_greater_than(&numbers, 5);
    for num in &filtered {
        print!("{} ", num);
    }
