#include <iostream>

bool is_armstrong(int num) {
    int original = num, sum = 0;
    while (num > 0) {
        int digit = num % 10;
        sum += digit * digit * digit;
        num /= 10;
    }
    return sum == original;
}

int main() {
    std::cout << "Is 153 an Armstrong number? " << is_armstrong(153) << std::endl;
    return 0;
}

rust_code:
fn is_armstrong(num: i32) -> bool {
    let original = num;
    let sum: i32 = num.to_string().chars()
        .map(|d| d.to_digit(10).unwrap() as i32)
        .map(|d| d * d * d)
        .sum();
    sum == original
}

fn main() {
    println!("Is 153 an Armstrong number? {}", is_armstrong(153));
}

