void rotate_left(std::vector<int>& vec) {
    if (!vec.empty()) {
        int first = vec.front();
        vec.erase(vec.begin());
        vec.push_back(first);
    }
}

int main() {
    std::vector<int> numbers = {1, 2, 3, 4, 5};
    rotate_left(numbers);
    for (int num : numbers) {
        std::cout << num << " ";
    }
    std::cout << std::endl;
    return 0;
}

rust_code:
fn rotate_left(vec: &mut Vec<i32>) {
    if !vec.is_empty() {
        let first = vec.remove(0);
        vec.push(first);
    }
}

fn main() {
    let mut numbers = vec![1, 2, 3, 4, 5];
    rotate_left(&mut numbers);
    for num in &numbers {
        print!("{} ", num);
    }
    println!();
}

