void remove_duplicates(std::vector<int>& vec) {
    std::vector<int> unique;
    for (int num : vec) {
        if (std::find(unique.begin(), unique.end(), num) == unique.end()) {
            unique.push_back(num);
        }
    }
    vec = unique;
}

