bool is_happy_number(int num) {
    int slow = num, fast = num;
    auto get_next = [](int n) {
        int sum = 0;
        while (n > 0) {
            int digit = n % 10;
            sum += digit * digit;
            n /= 10;
        }
        return sum;
    };
    do {
        slow = get_next(slow);
        fast = get_next(get_next(fast));
    } while (slow != fast);

    return slow == 1;
}

int main() {
    std::cout << "Is 19 a happy number? " << is_happy_number(19) << std::endl;
    return 0;
}

rust_code:
fn get_next(mut num: i32) -> i32 {
    let mut sum = 0;
    while num > 0 {
        let digit = num % 10;
        sum += digit * digit;
        num /= 10;
    }
    sum
}

fn is_happy_number(mut num: i32) -> bool {
    let mut slow = num;
    let mut fast = num;

    loop {
        slow = get_next(slow);
        fast = get_next(get_next(fast));

        if slow == fast {
            break;
        }
    }

    slow == 1
}

fn main() {
    println!("Is 19 a happy number? {}", is_happy_number(19));
}

