bool is_strong_number(int num) {
    int original = num, sum = 0;
    auto factorial = [](int n) {
        int fact = 1;
        for (int i = 2; i <= n; i++) fact *= i;
        return fact;
    };

    while (num > 0) {
        sum += factorial(num % 10);
        num /= 10;
    }
    return sum == original;
}

