    let original = num;
    let sum: i32 = num.to_string().chars()
        .map(|c| factorial(c.to_digit(10).unwrap() as i32))
        .sum();
    sum == original
}

fn main() {
    println!("Is 145 a strong number? {}", is_strong_number(145));
}

