bool is_circular_prime(int num) {
    auto is_prime = [](int n) {
        if (n < 2) return false;
        for (int i = 2; i * i <= n; i++) {
            if (n % i == 0) return false;
        }
        return true;
    };

    std::string str = std::to_string(num);
    for (size_t i = 0; i < str.length(); i++) {
        std::rotate(str.begin(), str.begin() + 1, str.end());
        if (!is_prime(std::stoi(str))) return false;
    }
    return true;
}

