        if n % i == 0 {
            return false;
        }
    }
    true
}

fn is_circular_prime(num: u32) -> bool {
    let mut str_num = num.to_string();
    for _ in 0..str_num.len() {
        str_num = format!("{}{}", &str_num[1..], &str_num[..1]);
        if !is_prime(str_num.parse().unwrap()) {
            return false;
        }
    }
    true
}

