    std::string str = std::to_string(num);
    int mid = str.length() / 2, left_sum = 0, right_sum = 0;

    for (size_t i = 0; i < mid; i++) {
        left_sum += str[i] - '0';
        right_sum += str[str.length() - 1 - i] - '0';
    }

    return left_sum == right_sum;
}

int main() {
    std::cout << "Is 123321 a balanced number? " << is_balanced_number(123321) << std::endl;
    return 0;
}

