fn is_balanced_number(num: i32) -> bool {
    let str_num = num.to_string();
    let mid = str_num.len() / 2;
    let left_sum: i32 = str_num.chars().take(mid).map(|c| c.to_digit(10).unwrap() as i32).sum();
    let right_sum: i32 = str_num.chars().rev().take(mid).map(|c| c.to_digit(10).unwrap() as i32).sum();

    left_sum == right_sum
}

fn main() {
    println!("Is 123321 a balanced number? {}", is_balanced_number(123321));
