bool is_super_prime(int num) {
    auto is_prime = [](int n) {
        if (n < 2) return false;
        for (int i = 2; i * i <= n; i++) {
            if (n % i == 0) return false;
        }
        return true;
    };

    if (!is_prime(num)) return false;

    int index = 1, count = 0;
    for (int i = 2; count < num; i++) {
        if (is_prime(i)) {
            count++;
            if (i == num) return is_prime(index);
            index++;
        }
    }
    return false;
}

