bool is_alternating_bit_number(int num) {
    int last_bit = num & 1;
    num >>= 1;

    while (num > 0) {
        int current_bit = num & 1;
        if (current_bit == last_bit) return false;
        last_bit = current_bit;
        num >>= 1;
    }
    return true;
}

int main() {
    std::cout << "Is 5 an alternating bit number? " << is_alternating_bit_number(5) << std::endl;
    return 0;
}

