    let mut last_bit = num & 1;
    num >>= 1;

    while num > 0 {
        let current_bit = num & 1;
        if current_bit == last_bit {
            return false;
        }
        last_bit = current_bit;
        num >>= 1;
    }
    true
}

fn main() {
    println!("Is 5 an alternating bit number? {}", is_alternating_bit_number(5));
