void rotate_array(int arr[], int size, int k) {
    k = k % size;
    int temp[k];

    for (int i = 0; i < k; i++) {
        temp[i] = arr[i];
    }

    for (int i = 0; i < size - k; i++) {
        arr[i] = arr[i + k];
    }

    for (int i = 0; i < k; i++) {
        arr[size - k + i] = temp[i];
    }
}

int main() {
    int arr[] = {1, 2, 3, 4, 5};
    rotate_array(arr, 5, 2);
    for (int i = 0; i < 5; i++) {
        std::cout << arr[i] << " ";
    }
    return 0;
}

rust_code:
fn rotate_array(arr: &mut Vec<i32>, k: usize) {
    let k = k % arr.len();
    arr.rotate_left(k);
}

fn main() {
    let mut arr = vec![1, 2, 3, 4, 5];
    rotate_array(&mut arr, 2);
    println!("{:?}", arr);
}

