std::vector<int> merge_sorted_arrays(std::vector<int> arr1, std::vector<int> arr2) {
    std::vector<int> merged;
    size_t i = 0, j = 0;

    while (i < arr1.size() && j < arr2.size()) {
        if (arr1[i] < arr2[j]) merged.push_back(arr1[i++]);
        else merged.push_back(arr2[j++]);
    }

    while (i < arr1.size()) merged.push_back(arr1[i++]);
    while (j < arr2.size()) merged.push_back(arr2[j++]);

    return merged;
}

int main() {
    std::vector<int> arr1 = {1, 3, 5}, arr2 = {2, 4, 6};
    std::vector<int> result = merge_sorted_arrays(arr1, arr2);
    for (int num : result) std::cout << num << " ";
    return 0;
}

rust_code:
fn merge_sorted_arrays(arr1: &[i32], arr2: &[i32]) -> Vec<i32> {
    let mut merged = Vec::new();
    let (mut i, mut j) = (0, 0);

    while i < arr1.len() && j < arr2.len() {
        if arr1[i] < arr2[j] {
            merged.push(arr1[i]);
            i += 1;
        } else {
            merged.push(arr2[j]);
            j += 1;
        }
    }

    merged.extend_from_slice(&arr1[i..]);
    merged.extend_from_slice(&arr2[j..]);

    merged
}

fn main() {
    let arr1 = [1, 3, 5];
    let arr2 = [2, 4, 6];
    let result = merge_sorted_arrays(&arr1, &arr2);
    println!("{:?}", result);
}

