std::string shift_string(std::string str, int shift) {
    for (char &c : str) {
        if (std::isalpha(c)) {
            char base = std::islower(c) ? 'a' : 'A';
            c = (c - base + shift) % 26 + base;
        }
    }
    return str;
}

int main() {
    std::cout << shift_string("abc", 2) << std::endl;
    return 0;
}

rust_code:
fn shift_string(text: &str, shift: u8) -> String {
    text.chars()
        .map(|c| {
            if c.is_alphabetic() {
                let base = if c.is_lowercase() { 'a' } else { 'A' };
                ((c as u8 - base as u8 + shift) % 26 + base as u8) as char
            } else {
                c
            }
        })
        .collect()
}

fn main() {
    println!("{}", shift_string("abc", 2));
}

