std::vector<int> cumulative_difference(const std::vector<int>& vec) {
    std::vector<int> result(vec.size());
    result[0] = vec[0];
    for (size_t i = 1; i < vec.size(); i++) {
        result[i] = result[i - 1] - vec[i];
    }
    return result;
}

int main() {
    std::vector<int> vec = {10, 3, 2, 1};
    std::vector<int> differences = cumulative_difference(vec);
    for (int num : differences) std::cout << num << " ";
    return 0;
}

rust_code:
fn cumulative_difference(vec: &[i32]) -> Vec<i32> {
    let mut result = vec.to_vec();
    for i in 1..vec.len() {
        result[i] = result[i - 1] - vec[i];
    }
    result
}

fn main() {
    let vec = vec![10, 3, 2, 1];
    let differences = cumulative_difference(&vec);
    println!("{:?}", differences);
}

