std::string swap_case(std::string str) {
    for (char &c : str) {
        if (std::islower(c)) c = std::toupper(c);
        else if (std::isupper(c)) c = std::tolower(c);
    }
    return str;
}

int main() {
    std::cout << swap_case("Hello World") << std::endl;
    return 0;
}

rust_code:
fn swap_case(text: &str) -> String {
    text.chars()
        .map(|c| if c.is_lowercase() { c.to_ascii_uppercase() } else { c.to_ascii_lowercase() })
        .collect()
}

fn main() {
    println!("{}", swap_case("Hello World"));
}

