    std::vector<int> result(vec.size());
    for (size_t i = 0; i < vec.size(); i += 2) {
        if (i + 1 < vec.size()) {
            result[i] = vec[i + 1];
            result[i + 1] = vec[i];
        } else {
            result[i] = vec[i];
        }
    }
    return result;
}

