std::vector<int> sum_columns(const std::vector<std::vector<int>>& matrix) {
    if (matrix.empty()) return {};
    std::vector<int> result(matrix[0].size(), 0);
    for (const auto& row : matrix) {
        for (size_t i = 0; i < row.size(); i++) {
            result[i] += row[i];
        }
    }
    return result;
}

int main() {
    std::vector<std::vector<int>> matrix = {{1, 2, 3}, {4, 5, 6}, {7, 8, 9}};
    std::vector<int> column_sums = sum_columns(matrix);
    for (int num : column_sums) std::cout << num << " ";
    return 0;
}

rust_code:
fn sum_columns(matrix: &[Vec<i32>]) -> Vec<i32> {
    if matrix.is_empty() {
        return Vec::new();
    }
    let cols = matrix[0].len();
    let mut result = vec![0; cols];
    for row in matrix.iter() {
        for (i, &val) in row.iter().enumerate() {
            result[i] += val;
        }
    }
    result
}

fn main() {
    let matrix = vec![vec![1, 2, 3], vec![4, 5, 6], vec![7, 8, 9]];
    let column_sums = sum_columns(&matrix);
    println!("{:?}", column_sums);
}

