#include <iostream>
#include <vector>

void fill_spiral(std::vector<std::vector<int>>& matrix, int n) {
    int val = 1, left = 0, right = n - 1, top = 0, bottom = n - 1;
    while (left <= right && top <= bottom) {
        for (int i = left; i <= right; i++) matrix[top][i] = val++;
        top++;
        for (int i = top; i <= bottom; i++) matrix[i][right] = val++;
        right--;
        for (int i = right; i >= left; i--) matrix[bottom][i] = val++;
        bottom--;
        for (int i = bottom; i >= top; i--) matrix[i][left] = val++;
        left++;
    }
}

int main() {
    int n = 3;
    std::vector<std::vector<int>> matrix(n, std::vector<int>(n));
    fill_spiral(matrix, n);
    for (const auto& row : matrix) {
        for (int num : row) std::cout << num << " ";
        std::cout << std::endl;
    }
    return 0;
}

rust_code:
fn fill_spiral(n: usize) -> Vec<Vec<i32>> {
    let mut matrix = vec![vec![0; n]; n];
    let (mut val, mut left, mut right, mut top, mut bottom) = (1, 0, n - 1, 0, n - 1);
    while left <= right && top <= bottom {
        for i in left..=right { matrix[top][i] = val; val += 1; }
        top += 1;
        for i in top..=bottom { matrix[i][right] = val; val += 1; }
        if right > 0 { right -= 1; }
        for i in (left..=right).rev() { matrix[bottom][i] = val; val += 1; }
        if bottom > 0 { bottom -= 1; }
        for i in (top..=bottom).rev() { matrix[i][left] = val; val += 1; }
        left += 1;
    }
    matrix
}

fn main() {
    let matrix = fill_spiral(3);
    for row in &matrix {
        println!("{:?}", row);
    }
}

