std::vector<int> reverse_chunks(const std::vector<int>& vec, int chunk_size) {
    std::vector<int> result = vec;
    for (size_t i = 0; i < vec.size(); i += chunk_size) {
        size_t end = std::min(i + chunk_size, vec.size());
        std::reverse(result.begin() + i, result.begin() + end);
    }
    return result;
}

int main() {
    std::vector<int> vec = {1, 2, 3, 4, 5, 6};
    std::vector<int> reversed = reverse_chunks(vec, 2);
    for (int num : reversed) std::cout << num << " ";
    return 0;
}

rust_code:
fn reverse_chunks(vec: &[i32], chunk_size: usize) -> Vec<i32> {
    let mut result = vec.to_vec();
    for i in (0..vec.len()).step_by(chunk_size) {
        let end = (i + chunk_size).min(vec.len());
        result[i..end].reverse();
    }
    result
}

fn main() {
    let vec = vec![1, 2, 3, 4, 5, 6];
    let reversed = reverse_chunks(&vec, 2);
    println!("{:?}", reversed);
}

