std::string replace_substring(const std::string& str, const std::string& old_sub, const std::string& new_sub) {
    std::string result = str;
    size_t pos = 0;
    while ((pos = result.find(old_sub, pos)) != std::string::npos) {
        result.replace(pos, old_sub.length(), new_sub);
        pos += new_sub.length();
    }
    return result;
}

