    for (auto it = matrix.back().rbegin(); it != matrix.back().rend(); ++it) {
        result.push_back(*it);
    }
    for (size_t i = matrix.size() - 2; i > 0; i--) {
        result.push_back(matrix[i].front());
    }

    return result;
}

int main() {
    std::vector<std::vector<int>> matrix = {{1, 2, 3}, {4, 5, 6}, {7, 8, 9}};
    std::vector<int> border = extract_border_elements(matrix);
    for (int num : border) std::cout << num << " ";
    return 0;
}

rust_code:
fn extract_border_elements(matrix: &[Vec<i32>]) -> Vec<i32> {
    let mut result = Vec::new();
    if matrix.is_empty() {
        return result;
    }

    for &num in &matrix[0] {
        result.push(num);
    }
    for i in 1..matrix.len() - 1 {
        if let Some(&num) = matrix[i].last() {
            result.push(num);
        }
    }
    if let Some(last_row) = matrix.last() {
        for &num in last_row.iter().rev() {
            result.push(num);
        }
    }
    for i in (1..matrix.len() - 1).rev() {
        if let Some(&num) = matrix[i].first() {
            result.push(num);
        }
    }

    result
}

fn main() {
    let matrix = vec![vec![1, 2, 3], vec![4, 5, 6], vec![7, 8, 9]];
    let border = extract_border_elements(&matrix);
    println!("{:?}", border);
}

