fn is_prime(num: usize) -> bool {
    if num < 2 { return false; }
    for i in 2..=((num as f64).sqrt() as usize) {
        if num % i == 0 { return false; }
    }
    true
}

fn extract_prime_indices(vec: &[i32]) -> Vec<i32> {
    vec.iter().enumerate().filter_map(|(i, &x)| if is_prime(i) { Some(x) } else { None }).collect()
}

