std::vector<int> reverse_in_groups(std::vector<int> vec, int group_size) {
    for (size_t i = 0; i < vec.size(); i += group_size) {
        size_t end = std::min(i + group_size, vec.size());
        std::reverse(vec.begin() + i, vec.begin() + end);
    }
    return vec;
}

int main() {
    std::vector<int> vec = {1, 2, 3, 4, 5, 6};
