std::vector<int> reverse_every_n_elements(std::vector<int> vec, int n) {
    for (size_t i = 0; i < vec.size(); i += n) {
        size_t end = std::min(i + n, vec.size());
        std::reverse(vec.begin() + i, vec.begin() + end);
    }
    return vec;
}

int main() {
    std::vector<int> vec = {1, 2, 3, 4, 5, 6, 7, 8};
    std::vector<int> reversed = reverse_every_n_elements(vec, 3);
    for (int num : reversed) std::cout << num << " ";
    return 0;
}

