fn reverse_every_n_elements(vec: &[i32], n: usize) -> Vec<i32> {
    let mut result = vec.to_vec();
    for i in (0..vec.len()).step_by(n) {
        let end = (i + n).min(vec.len());
        result[i..end].reverse();
    }
    result
}

fn main() {
    let vec = vec![1, 2, 3, 4, 5, 6, 7, 8];
    let reversed = reverse_every_n_elements(&vec, 3);
    println!("{:?}", reversed);
}

