std::vector<int> rotate_matrix_diagonal(std::vector<std::vector<int>> matrix) {
    size_t n = matrix.size();
    for (size_t i = 0; i < n; i++) {
        for (size_t j = i + 1; j < n; j++) {
            std::swap(matrix[i][j], matrix[j][i]);
        }
    }
    return matrix;
}

int main() {
    std::vector<std::vector<int>> matrix = {{1, 2, 3}, {4, 5, 6}, {7, 8, 9}};
    matrix = rotate_matrix_diagonal(matrix);
    for (const auto& row : matrix) {
        for (int num : row) std::cout << num << " ";
        std::cout << std::endl;
    }
    return 0;
}

rust_code:
fn rotate_matrix_diagonal(matrix: &mut Vec<Vec<i32>>) {
    let n = matrix.len();
    for i in 0..n {
        for j in i + 1..n {
            let temp = matrix[i][j];
            matrix[i][j] = matrix[j][i];
            matrix[j][i] = temp;
        }
    }
}

fn main() {
    let mut matrix = vec![vec![1, 2, 3], vec![4, 5, 6], vec![7, 8, 9]];
    rotate_matrix_diagonal(&mut matrix);
    for row in &matrix {
        println!("{:?}", row);
    }
}

