std::vector<int> reverse_even_indices(const std::vector<int>& vec) {
    std::vector<int> result(vec);
    size_t left = 0, right = (vec.size() % 2 == 0) ? vec.size() - 2 : vec.size() - 1;
    while (left < right) {
        std::swap(result[left], result[right]);
        left += 2;
        right -= 2;
    }
    return result;
}

int main() {
    std::vector<int> vec = {10, 20, 30, 40, 50, 60};
    std::vector<int> reversed = reverse_even_indices(vec);
    for (int num : reversed) std::cout << num << " ";
    return 0;
}

