    let mut result = vec.to_vec();
    let mut left = 0;
    let mut right = if vec.len() % 2 == 0 { vec.len() - 2 } else { vec.len() - 1 };
    while left < right {
        result.swap(left, right);
        left += 2;
        right -= 2;
    }
    result
}

fn main() {
    let vec = vec![10, 20, 30, 40, 50, 60];
    let reversed = reverse_even_indices(&vec);
    println!("{:?}", reversed);
}

