std::vector<int> sum_of_neighbors(const std::vector<int>& vec) {
    std::vector<int> result(vec.size(), 0);
    for (size_t i = 1; i < vec.size() - 1; i++) {
        result[i] = vec[i - 1] + vec[i + 1];
    }
    if (!vec.empty()) {
        result[0] = vec[1];
        result[vec.size() - 1] = vec[vec.size() - 2];
    }
    return result;
}

int main() {
    std::vector<int> vec = {3, 8, 2, 7, 4};
    std::vector<int> summed = sum_of_neighbors(vec);
