fn sum_of_neighbors(vec: &[i32]) -> Vec<i32> {
    let mut result = vec![0; vec.len()];
    if vec.len() > 1 {
        result[0] = vec[1];
        result[vec.len() - 1] = vec[vec.len() - 2];
    }
    for i in 1..vec.len()-1 {
        result[i] = vec[i - 1] + vec[i + 1];
    }
    result
}

fn main() {
    let vec = vec![3, 8, 2, 7, 4];
    let summed = sum_of_neighbors(&vec);
    println!("{:?}", summed);
