void shuffle_alternate(std::vector<int>& vec) {
    std::vector<int> first_half(vec.begin(), vec.begin() + vec.size() / 2);
    std::vector<int> second_half(vec.begin() + vec.size() / 2, vec.end());
    vec.clear();
    size_t max_size = std::max(first_half.size(), second_half.size());
    for (size_t i = 0; i < max_size; i++) {
        if (i < first_half.size()) vec.push_back(first_half[i]);
        if (i < second_half.size()) vec.push_back(second_half[i]);
    }
}

int main() {
    std::vector<int> vec = {1, 2, 3, 4, 5, 6};
    shuffle_alternate(vec);
    for (int num : vec) std::cout << num << " ";
    return 0;
}

rust_code:
fn shuffle_alternate(vec: &mut Vec<i32>) {
    let mid = vec.len() / 2;
    let first_half = vec[..mid].to_vec();
    let second_half = vec[mid..].to_vec();
    vec.clear();
    let max_size = first_half.len().max(second_half.len());
    for i in 0..max_size {
        if i < first_half.len() { vec.push(first_half[i]); }
        if i < second_half.len() { vec.push(second_half[i]); }
    }
}

fn main() {
    let mut vec = vec![1, 2, 3, 4, 5, 6];
    shuffle_alternate(&mut vec);
    println!("{:?}", vec);
}

