fn wrap_text(s: &str, width: usize) -> String {
    let mut result = String::new();
    let mut count = 0;
    for c in s.chars() {
        if count >= width && c == ' ' {
            result.push('
');
            count = 0;
        } else {
            result.push(c);
            count += 1;
        }
    }
    result
}

