        if (i == 0 || str[i] != str[i - 1]) {
            result += str[i];
        }
    }
    return result;
}

int main() {
    std::string input = "aabbccddeeff";
    std::string modified = remove_duplicate_adjacent_characters(input);
    std::cout << modified << std::endl;
    return 0;
}

