fn remove_duplicate_adjacent_characters(s: &str) -> String {
    let mut result = String::new();
    let mut prev: Option<char> = None;
    for c in s.chars() {
        if Some(c) != prev {
            result.push(c);
        }
        prev = Some(c);
    }
    result
}

